SELECT CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, s.country, ROUND(AVG(ss.revenue), 2) AS avg_revenue, MIN(ss.units) AS min_units FROM store_sales ss LEFT OUTER JOIN products p ON ss.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END, s.country ORDER BY rating_bucket DESC;
